  [274276] = { "Aumenta la Tempra di $N1. Mentre ti trovi sul ⟦Mount Hyjal=Monte Hyjal⟧, a Hyjal Summit o a Barrow Deeps, inoltre, la tua celerità aumenta del $N2%.\n\nDura $D1. Puoi avere attivo l'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", 0x8dfaab82, "u" },
